pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address operator, address from, uint256 id, bytes calldata data) public {
        vm.assume(operator != address(0));
        vm.assume(from != address(0));
        bytes4 expected = bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
        bytes4 actual = c.onERC721Received(operator, from, id, data);
        assertTrue(actual == expected);
    }
}
